using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a Web App by its short name. Returns a 404 error if the Web App is not found
    /// </summary>
    public Task<TdLib.TdApi.Objects.FoundWebApp> SearchWebAppAsync(long botUserId = default, string webAppShortName = default)
    {

           using var activity =  StartCallActivity("SearchWebAppAsync", typeof(SearchWebApp).FullName ?? "SearchWebAppAsync");

           try
           {
             return client.SearchWebAppAsync(botUserId, webAppShortName);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd